export const ICON_EXCEPTIONS: Record<string, string> = {
  "b.a.b.y dragon": "baby-dragon",
  "l.a.s.s.i": "lassi",
  "l.a.s.s.i.": "lassi",
  "lassi": "lassi",
  "p.e.k.k.a": "pekka",
  "p.e.k.k.a.": "pekka",
  "pekka": "pekka",
  "power p.e.k.k.a": "power-pekka",
  "power p.e.k.k.a.": "power-pekka",
  "super p.e.k.k.a": "super-pekka",
};

/**
 * Normalizes a unit, hero, equipment, pet or spell name to match manifest keys.
 */
export function normalizeIconKey(name?: string | null, village?: string | null): string {
  if (!name) return "";
  const raw = name.trim().toLowerCase();
  if (village && village.toLowerCase().includes("builder") && (raw === "baby dragon" || raw === "baby-dragon")) {
    return "builder-baby-dragon";
  }
  if (ICON_EXCEPTIONS[raw]) {
    return ICON_EXCEPTIONS[raw];
  }
  const cleaned = raw.replace(/['\.]/g, "").replace(/[^a-z0-9]+/g, "-");
  return cleaned.replace(/^-+|-+$/g, "");
}

