/**
 * Resolves the relative icon URL for a given unit/equipment/spell name.
 * Returns null if no matching icon file is found.
 */
export function getIconPath(name?: string | null, village?: string | null): string | null {
  if (!name) return null;
  const key = normalizeIconKey(name, village);
  if (ICON_MANIFEST[key]) return ICON_MANIFEST[key];
  // Fallback check with/without -spell
  if (ICON_MANIFEST[`${key}-spell`]) return ICON_MANIFEST[`${key}-spell`];
  if (key.endsWith("-spell") && ICON_MANIFEST[key.slice(0, -6)]) {
    return ICON_MANIFEST[key.slice(0, -6)];
  }
  return null;
}
